 "content": "from collections import Counter

def transform(grid):
    # Recolor the most common/background color to 0 and the other color to the background color.
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    foreground = next(v for row in grid for v in row if v != background)
    return [[0 if v == background else background if v == foreground else v for v in row] for row in grid]
